for (const cluster of clusters) {
  const segmentIds = cluster.segments.split('|');
  cluster.evidenceRefs = [...new Set(segmentIds.flatMap(id => [
    `SERP-${id.toUpperCase()}`,
    ...(id === 'private' || id === 'rescue' ? ['FP-GSC-02'] : []),
    ...(id === 'prime-a' ? ['SITE-01'] : []),
  ]))].join('|');
  cluster.evidenceConfidence = cluster.id === 'private-service'
    ? 'medium — direct page signal, small sample'
    : cluster.status.startsWith('existing')
      ? 'low-medium — existing owner, limited query evidence'
      : 'directional — current SERP pattern, no first-party cluster signal';
  cluster.marketMetricStatus = 'unavailable-not-zero';
  cluster.rankingValidationScope = 'representative cluster-primary SERP; exact long-tail rank not claimed';
}

function clusterFor(segmentId, layer, query) {
  const s = segments.find(x=>x.id===segmentId);
  if (segmentId==='rescue' && /power of sale/i.test(query)) return 'rescue-legal';
  if (segmentId==='rescue') return layer==='L5' || /lender|refinanc|private/i.test(query) && layer==='L4' ? 'private-service' : 'rescue-guide';
  if (layer==='L3' && ['prime-a','alternative-b','private'].includes(segmentId)) return 'lender-comparison';
  if (layer==='L3' && ['heloc-equity','renovation'].includes(segmentId)) return 'equity-comparison';
  if (layer==='L3' && segmentId==='bridge') return 'bridge-guide';
  if (layer==='L3' && segmentId==='residential') return 'residential-guide';
  return ['L1','L2'].includes(layer) ? s.guide : s.service;
}

const keywords = [];
let kid=1;
for (const segment of segments) {
  for (const [layerCode, layerName] of layers) {
    for (const query of queries[segment.id][layerCode]) {
      const clusterId=clusterFor(segment.id,layerCode,query);
      const cluster=clusters.find(c=>c.id===clusterId);
      const exactGsc=query.toLowerCase()==='fair market value appraisal for private lending';
      keywords.push({
        id:`KW-${String(kid++).padStart(3,'0')}`,query,normalizedQuery:query.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),segmentId:segment.id,segmentName:segment.name,
        borrowerProfile:segment.profile,financingTrigger:segment.trigger,primaryFunnelLayer:layerCode,layerName,secondaryFunnelLayer:layerCode==='L5'?'L4':'',
        intent:layerCode==='L1'?'informational':layerCode==='L2'?'informational-feasibility':layerCode==='L3'?'commercial-comparison':layerCode==='L4'?'commercial-investigation':'transactional-urgent',
        geography:/Toronto/i.test(query)?'Toronto/GTA':/Canada/i.test(query)?'Canada with Ontario application':'Ontario',clusterId,targetPath:cluster.path,pageType:cluster.type,
        priority:cluster.priority,disposition:'Retain',evidenceClass:exactGsc?'first-party exact-query + current SERP':'current SERP / first-party directional',
        marketMetricStatus:'unavailable-not-zero',monthlySearches:'',cpc:'',difficulty:'',gscClicks:exactGsc?'0':'',gscImpressions:exactGsc?'2':'',gscCtr:exactGsc?'0':'',gscPosition:exactGsc?'96.5':'',
        fairlendGscStatus:exactGsc?'exact query observed in fresh GSC':'not observed in fresh visible GSC query sample; unavailable-not-zero',
        serpValidationQuery:cluster.primary,rankingScope:'cluster-primary SERP; not claimed as exact-query rank',currentRankingUrls:serpBySegment[segment.id].join(' | '),observedAt,confidence:exactGsc?'medium':'directional',
        sourceRefs:`${exactGsc?'FP-GSC-03|':''}SERP-${segment.id.toUpperCase()};KP-UNAVAILABLE`,rationale:`Supports ${cluster.name}; ${cluster.boundary}`
      });
    }
  }
}

