  'prime-a':'an A-lender mortgage','alternative-b':'a B-lender or alternative mortgage',private:'a private mortgage',residential:'a residential mortgage',renovation:'renovation financing',bridge:'bridge financing','heloc-equity':'a HELOC or home-equity loan',rescue:'mortgage-decline or rescue financing'
