function csv(rows) {
  if(!rows.length) return '';
  const cols=Object.keys(rows[0]);
  const esc=v=>'"'+String(v??'').replaceAll('"','""')+'"';
  return [cols.map(esc).join(','),...rows.map(r=>cols.map(c=>esc(r[c])).join(','))].join('\n')+'\n';
}

function report() {
  const clusterRows=clusters.map(c=>`| ${c.priority} | \`${c.path}\` | ${c.status} | ${c.name} | ${c.layers} | ${c.evidenceConfidence} | ${c.boundary} |`).join('\n');
  const oppRows=opportunities.map(o=>`| ${o.priority} | ${o.service} | ${o.firstPartySignal} | ${o.recommendedAction} |`).join('\n');
  const boundaryRows=boundaries.map(b=>`| ${b[0]} | ${b[1]} |`).join('\n');
  const briefs=clusters.map(c=>`### ${c.name} — ${c.priority}\n\n- **Canonical owner:** \`${c.path}\` (${c.status})\n- **Primary query:** ${c.primary}\n- **Segments / layers:** ${c.segments}; ${c.layers}\n- **Borrower problem:** ${c.problem}\n- **Promised outcome:** ${c.outcome}\n- **Required sections:** ${c.sections}\n- **CTA:** ${c.cta}\n- **Internal links:** ${c.links}\n- **Evidence references:** ${c.evidenceRefs}\n- **Evidence confidence:** ${c.evidenceConfidence}\n- **Market metrics:** ${c.marketMetricStatus}\n- **Ranking validation scope:** ${c.rankingValidationScope}\n- **Boundary:** ${c.boundary}\n`).join('\n');
  return `# FairLend mortgage-borrower keyword research, five-layer clustering, and content proposal\n\n**Market:** Ontario, with Toronto/GTA differentiation only where material  \n**Observed:** ${observedAt}  \n**Google account:** c.beleznay@humanfeedback.com  \n**Coverage:** 8 borrower/service segments · 5 funnel layers · ${keywords.length} retained keywords · ${clusters.length} canonical page clusters · ${questions.length} questions\n\n## Executive decision\n\nFairLend should build a borrower decision system, not a collection of near-duplicate mortgage pages. The immediate P0 is to strengthen the existing \`/borrowers/private-mortgage-financing\` owner, publish one A-vs-B-vs-private decision page, and add a mortgage-decline triage guide that routes commercial urgency back to the private owner. The existing institutional page should be sharpened as the prime/A owner. B, HELOC, bridge, and renovation each need a bounded guide/service pair. Generic residential expansion is P2 because the current 67-impression GSC sample shows no demand signal for it.\n\nMarket search volume, CPC, and difficulty could not be retrieved from a callable provider. Those cells are deliberately blank and marked **unavailable-not-zero**. Current ranking-page evidence is attached at the segment/cluster-primary level; the dataset does not misrepresent a cluster SERP as an exact rank for every long-tail variant.\n\n## First-party Google validation\n\n- GSC property \`sc-domain:fairlend.ca\`: **2 clicks / 67 impressions / 3% CTR / average position 31.2**. This is a small diagnostic sample, not market demand.\n- Existing private borrower page: **14 impressions / 0 clicks / average position 10.07**. It is the strongest direct borrower-page signal and must remain the canonical commercial owner.\n- Exact visible query \`fair market value appraisal for private lending\`: **2 impressions / 0 clicks / average position 96.5**. This supports an appraisal/equity section, not a new page.\n- GA4 property \`502729166\`, 2026-06-22–2026-07-19: **18 sessions, 14 engaged; organic 3 sessions, 2 engaged, 66.67% engagement, 77s average engagement, 23 events, 0 key events**.\n- Measurement blocker: zero configured key events means GA4 cannot validate lead quality yet.\n\n## Evidence taxonomy\n\n1. **Fresh numeric first-party:** authenticated GSC/GA4 UI observations.\n2. **Current ranking-page / SERP pattern:** current pages appearing for representative cluster queries; used for content type and boundary decisions.\n3. **Third-party discovery:** Answer Socrates/PAA-style question expansion; qualitative only.\n4. **Semantic hypothesis:** unobserved long-tail variants retained because they express a distinct borrower question inside a validated page owner.\n5. **Unavailable-not-zero:** no connected paid keyword metrics source. Blank volume/CPC/KD cells are unknown, never zero.\n\n## Five-layer funnel\n\n| Layer | Name | Job |\n|---|---|---|\n${layers.map(l=>`| ${l[0]} | ${l[1]} | ${l[2]} |`).join('\n')}\n\n## Service opportunity matrix\n\n| Priority | Service | First-party evidence | Action |\n|---|---|---|---|\n${oppRows}\n\n## Canonical architecture\n\n| Priority | Canonical path | Status | Page owner | Layers | Boundary |\n|---|---|---|---|---|---|\n${clusterRows}\n\n## Cannibalization contract\n\n| Boundary | Rule |\n|---|---|\n${boundaryRows}\n\n## Cluster briefs\n\n${briefs}\n## 90-day operating plan\n\n### Days 1–14 — measurement and owner repair\n\n- Configure GA4 key events for assessment start, completed lead form, phone/email click, and qualified-lead handoff.\n- Confirm canonical host and indexation for the two existing service owners.\n- Rewrite \`/borrowers/private-mortgage-financing\` around borrower scenarios, equity/appraisal, costs, exit, urgency, and a single assessment CTA.\n- Refocus \`/borrowers/institutional-mortgage\` as the prime/A service owner.\n- Add GSC annotations and a query→page export process.\n\n### Days 15–30 — decision and rescue layer\n\n- Publish \`/resources/a-vs-b-vs-private-mortgage\`.\n- Publish \`/resources/mortgage-declined-ontario\` as a triage guide, not a duplicate service page.\n- Build reusable comparison matrix, document checklist, evidence callout, and urgent-assessment modules.\n- Obtain legal review before any power-of-sale content; keep its URL on Hold until approved.\n\n### Days 31–60 — alternative and equity system\n\n- Publish the B-lender guide and alternative-mortgage service owner.\n- Publish HELOC guide/service plus the HELOC-vs-refinance-vs-renovation comparison.\n- Publish renovation guide/service with explicit construction boundary.\n- Add internal links from guides → comparison → canonical service; link service FAQs back to evidence guides.\n\n### Days 61–90 — bridge, residential, and validation\n\n- Publish bridge guide/service with firm-sale vs no-firm-sale modules.\n- Publish A-lender requirements guide.\n- Create residential guide/service only after P0/P1 owners are indexed and conversion tracking works.\n- Re-run GSC/GA4 at 28 days and again at day 90. Import market volume/CPC/KD when a provider becomes available; reprioritize without changing canonical ownership casually.\n\n## Measurement specification\n\n| KPI | Source | Cadence | Decision threshold |\n|---|---|---|---|\n| Non-brand impressions by cluster | GSC query→page export | Weekly | First signal; diagnose page/query mismatch |\n| CTR at positions 4–15 | GSC | Biweekly | Rewrite title/meta when impressions are sufficient |\n| Organic engaged sessions | GA4 | Weekly | Validate landing-page consumption |\n| Assessment starts/completions | GA4 key events | Weekly | Primary conversion signal after setup |\n| Qualified lead rate | CRM + GA4 join | Monthly | Determines commercial priority |\n| Cannibalization | GSC query→page | Monthly | Two pages repeatedly sharing one query family triggers consolidation |\n\n## How to use the CSVs\n\n- \`keyword-universe.csv\` is the one-row-per-query source of truth. Every retained query has one segment, layer, cluster, and owner.\n- \`page-cluster-map.csv\` is the page brief and canonical contract for strategy, writing, design, and development.\n- \`question-bank.csv\` drives FAQ, answer-first sections, comparison tables, and triage checklists.\n- \`evidence-ledger.csv\` separates numeric observation from qualitative discovery and semantic inference.\n- \`service-opportunity-matrix.csv\` is the prioritization view.\n- \`coverage-qa.csv\` records automated gates.\n\n## Limitations\n\n- No market-volume provider was callable; volume/CPC/KD are unavailable, not zero.\n- The current GSC sample is only 67 impressions and cannot validate broad demand.\n- Direct GSC UI did not provide a combined query→page export in this run, so cannibalization rules are preventive architecture, not an observed collision diagnosis.\n- SERP URLs validate representative page types and entities at segment/cluster level; exact rank positions for all ${keywords.length} long-tail queries were not available from a compliant bulk Google rank source.\n- Power-of-sale content requires Ontario legal review; this report is not legal advice.\n- Investor-only private mortgage intent is excluded. All retained queries serve borrowers.\n`;
}

function fullReport(){
  const statusSection = `## Search-demand and ranking validation status\n\n| Validation field | Coverage | Interpretation |\n|---|---:|---|\n| Retained keywords | ${keywords.length} | Every keyword has one segment, funnel layer, cluster, and canonical owner. |\n| Exact-query FairLend GSC observations | ${keywords.filter(k=>k.gscImpressions!=='').length} | One exact borrower query was visible; the other ${keywords.filter(k=>k.gscImpressions==='').length} are marked not observed, not zero. |\n| Market volume / CPC / difficulty | 0 provider-backed rows | No callable provider was available; values remain blank and unavailable-not-zero. |\n| Current ranking-page references | ${keywordValidation.length} rows | Each row carries three representative pages from its segment/cluster-primary SERP. |\n| Exact long-tail rank positions | unavailable | No compliant bulk Google rank source was accessible; representative SERP evidence is never presented as exact rank. |\n\nThe complete row-level validation is in \`keyword-demand-and-ranking-validation.csv\`. It keeps market demand, FairLend visibility, and external ranking-page evidence separate.\n\n`;
  return report()
    .replace('## Evidence taxonomy', statusSection + '## Evidence taxonomy')
    .replace('| Priority | Canonical path | Status | Page owner | Layers | Boundary |\n|---|---|---|---|---|---|', '| Priority | Canonical path | Status | Page owner | Layers | Evidence confidence | Boundary |\n|---|---|---|---|---|---|---|')
    .replace('- `page-cluster-map.csv` is the page brief', '- `keyword-demand-and-ranking-validation.csv` isolates market-metric availability, exact FairLend GSC visibility, and scoped current ranking-page references for all retained keywords.\n- `page-cluster-map.csv` is the page brief');
}

function roadmap(){return fullReport().split('## 90-day operating plan')[1].split('## Measurement specification')[0].trim().replace(/^/,'# FairLend 90-day borrower SEO roadmap\n\n');}

function htmlEscape(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}

function html(){
  const clusterCards=clusters.map(c=>`<article class="cluster" data-priority="${c.priority}" data-segment="${c.segments}"><div class="cluster-top"><span class="badge ${c.priority.toLowerCase()}">${c.priority}</span><span class="status">${htmlEscape(c.status)}</span></div><h3>${htmlEscape(c.name)}</h3><code>${htmlEscape(c.path)}</code><p>${htmlEscape(c.problem)}</p><dl><div><dt>Outcome</dt><dd>${htmlEscape(c.outcome)}</dd></div><div><dt>Layers</dt><dd>${c.layers}</dd></div><div><dt>CTA</dt><dd>${htmlEscape(c.cta)}</dd></div><div><dt>Boundary</dt><dd>${htmlEscape(c.boundary)}</dd></div></dl><details><summary>Full content brief</summary><p><b>Primary query:</b> ${htmlEscape(c.primary)}</p><p><b>Sections:</b> ${htmlEscape(c.sections)}</p><p><b>Internal links:</b> ${htmlEscape(c.links)}</p></details></article>`).join('');
  const opportunityRows=opportunities.map(o=>`<tr><td><span class="badge ${o.priority.toLowerCase()}">${o.priority}</span></td><td><b>${htmlEscape(o.service)}</b></td><td>${htmlEscape(o.firstPartySignal)}</td><td>${htmlEscape(o.serpDemandPattern)}</td><td>${htmlEscape(o.recommendedAction)}</td><td>${htmlEscape(o.confidence)}</td></tr>`).join('');
  const boundaryRows=boundaries.map((b,i)=>`<article class="rule"><span>0${i+1}</span><h3>${htmlEscape(b[0])}</h3><p>${htmlEscape(b[1])}</p></article>`).join('');
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FairLend Borrower SEO Operating Brief</title><style>
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&family=Inter:wght@400;500;600;700&family=Oxanium:wght@500;600&display=swap');
:root{--paper:#f4f0e8;--ink:#17211b;--muted:#5f685f;--line:#cbc8bd;--lime:#c9ff3d;--green:#153f2e;--cream:#fffdf7;--amber:#f0b84f;--red:#c15447;--font-serif:'Cormorant Garamond',Georgia,serif;--font-sans:Inter,Arial,sans-serif;--font-mono:Oxanium,monospace}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.58 var(--font-sans);background-image:radial-gradient(circle at 15% 0%,#fff 0,transparent 36%),linear-gradient(rgba(23,33,27,.025) 1px,transparent 1px);background-size:auto,28px 28px}a{color:#17613f;text-decoration-thickness:1px;text-underline-offset:3px}.wrap{max-width:1540px;margin:auto;display:grid;grid-template-columns:250px minmax(0,1fr);gap:42px;padding:28px}.toc{position:sticky;top:20px;align-self:start;border-top:6px solid var(--ink);padding-top:18px;display:flex;flex-direction:column;gap:5px;max-height:calc(100vh - 40px);overflow:auto}.toc-title{font:600 11px/1 var(--font-mono);letter-spacing:.18em;text-transform:uppercase;margin-bottom:12px}.toc a{display:block;color:var(--muted);text-decoration:none;padding:8px 10px;border-left:2px solid transparent}.toc a.active,.toc a:hover{background:#fff9;border-color:var(--green);color:var(--ink)}.main{min-width:0}.hero{background:var(--green);color:#fff;padding:58px clamp(28px,6vw,88px);border-radius:2px;position:relative;overflow:hidden}.hero:after{content:'5';position:absolute;right:-20px;bottom:-125px;font:700 330px/1 var(--font-serif);color:#ffffff0a}.eyebrow{font:600 11px/1 var(--font-mono);letter-spacing:.22em;text-transform:uppercase;color:var(--lime)}h1{font:600 clamp(48px,7vw,96px)/.88 var(--font-serif);letter-spacing:-.045em;max-width:980px;margin:24px 0}.hero p{font-size:18px;max-width:760px;color:#e6eee8}.hero-meta{display:flex;flex-wrap:wrap;gap:10px;margin-top:32px}.hero-meta span{border:1px solid #ffffff35;padding:7px 10px;font:500 11px var(--font-mono)}section{scroll-margin-top:28px;padding:54px 0;border-bottom:1px solid var(--line)}.sec-head{display:flex;align-items:baseline;gap:14px;margin-bottom:25px}.sec-head span{font:600 12px var(--font-mono);color:#17613f}.sec-head h2{margin:0;font:600 clamp(34px,4vw,54px)/1 var(--font-serif)}.lead{max-width:920px;font-size:18px}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin:28px 0}.kpi{background:var(--cream);border:1px solid var(--line);padding:20px}.kpi b{display:block;font:600 33px/1 var(--font-serif)}.kpi small{font:500 10px var(--font-mono);text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}.callout{border-left:7px solid var(--lime);background:var(--green);color:white;padding:24px 28px;margin:28px 0}.callout b{color:var(--lime)}.funnel{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.layer{background:var(--cream);border:1px solid var(--line);padding:20px;min-height:200px}.layer .num{font:600 36px var(--font-serif);color:#17613f}.layer h3{font:600 24px/1.05 var(--font-serif);margin:8px 0}.layer p{color:var(--muted);font-size:13px}.table-wrap{overflow:auto;background:var(--cream);border:1px solid var(--line)}table{width:100%;border-collapse:collapse;min-width:900px}th{position:sticky;top:0;background:var(--ink);color:#fff;text-align:left;font:600 10px var(--font-mono);letter-spacing:.08em;text-transform:uppercase;padding:14px}td{padding:14px;border-bottom:1px solid var(--line);vertical-align:top}tbody tr:nth-child(even){background:#edf0e8}.badge{display:inline-block;font:600 10px var(--font-mono);padding:4px 7px;background:#ddd}.p0{background:var(--lime);color:var(--ink)}.p1{background:#d5e8d8}.p2{background:#e9e4d8}.hold{background:#f4d7a2}.cluster-toolbar,.filters{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.filters button,.cluster-toolbar button{border:1px solid var(--line);background:var(--cream);padding:8px 11px;font:600 11px var(--font-mono);cursor:pointer}.filters button.active,.cluster-toolbar button.active{background:var(--green);color:white}.clusters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.cluster{background:var(--cream);border:1px solid var(--line);padding:22px;display:flex;flex-direction:column}.cluster[hidden]{display:none}.cluster-top{display:flex;justify-content:space-between;gap:8px}.status{font:500 9px var(--font-mono);color:var(--muted)}.cluster h3{font:600 26px/1.05 var(--font-serif);margin:18px 0 8px}.cluster code{display:block;overflow-wrap:anywhere;color:#17613f;font:500 11px var(--font-mono)}.cluster dl{margin-top:auto}.cluster dt{font:600 9px var(--font-mono);text-transform:uppercase;color:var(--muted)}.cluster dd{margin:2px 0 10px}.cluster details{border-top:1px solid var(--line);padding-top:10px}.cluster summary{cursor:pointer;font-weight:600}.rules{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.rule{background:var(--cream);padding:22px;border-left:4px solid var(--green)}.rule span{font:600 11px var(--font-mono);color:#17613f}.rule h3{font:600 24px var(--font-serif);margin:4px 0}.explorer-controls{display:grid;grid-template-columns:2fr repeat(3,1fr);gap:8px;margin:16px 0}.explorer-controls input,.explorer-controls select{width:100%;padding:11px;border:1px solid var(--line);background:var(--cream)}#keywordTable tbody tr[hidden],#questionTable tbody tr[hidden]{display:none}.roadmap{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.phase{background:var(--cream);border-top:7px solid var(--green);padding:22px}.phase h3{font:600 28px var(--font-serif);margin:3px 0}.phase ul{padding-left:18px}.evidence-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.evidence-card{background:var(--cream);border:1px solid var(--line);padding:22px}.evidence-card h3{font:600 24px var(--font-serif);margin:0}.fine{font-size:12px;color:var(--muted)}footer{padding:42px 0;color:var(--muted);font-size:12px}.count{font:600 11px var(--font-mono);color:#17613f}@media(max-width:1100px){.wrap{grid-template-columns:1fr}.toc{position:sticky;top:0;z-index:20;flex-direction:row;background:var(--paper);border-top:0;border-bottom:1px solid var(--line);padding:8px 0;overflow-x:auto;max-height:none}.toc-title{display:none}.toc a{white-space:nowrap;border-left:0;border-bottom:2px solid transparent}.toc a.active{border-bottom-color:var(--green)}.clusters{grid-template-columns:repeat(2,1fr)}.kpis{grid-template-columns:repeat(3,1fr)}.funnel{grid-template-columns:repeat(2,1fr)}}@media(max-width:680px){.wrap{padding:0 14px}.hero{margin:0 -14px;padding:42px 22px}.clusters,.rules,.roadmap,.evidence-grid,.funnel{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}.explorer-controls{grid-template-columns:1fr}.sec-head h2{font-size:36px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style></head><body><div class="wrap"><nav class="toc" id="toc"><div class="toc-title">Operating brief</div><a href="#s1">Decision</a><a href="#s2">Evidence</a><a href="#s3">Funnel</a><a href="#s4">Opportunity</a><a href="#s5">Architecture</a><a href="#s6">Boundaries</a><a href="#s7">Keywords</a><a href="#s8">Questions</a><a href="#s9">Roadmap</a><a href="#s10">Measurement</a></nav><div class="main">
<header class="hero"><div class="eyebrow">FairLend · Borrower SEO system · 20 July 2026</div><h1>From mortgage question to financeable outcome.</h1><p>A full Ontario borrower-search strategy across eight services and five intent layers—validated against authenticated first-party Google data and current ranking-page patterns, with one canonical owner for every retained query.</p><div class="hero-meta"><span>${keywords.length} keywords</span><span>${clusters.length} page owners</span><span>${questions.length} questions</span><span>8 services</span><span>5 layers</span><span>90-day plan</span></div></header>
<section id="s1"><div class="sec-head"><span>01</span><h2>The decision</h2></div><p class="lead">Strengthen the existing private-mortgage owner first. Then publish one lender-tier comparison and one decline-triage guide. Build B, HELOC, renovation, and bridge as bounded guide/service pairs. Keep generic residential expansion behind P0/P1 work until tracking and demand evidence improve.</p><div class="kpis"><div class="kpi"><b>2</b><small>GSC clicks</small></div><div class="kpi"><b>67</b><small>GSC impressions</small></div><div class="kpi"><b>14</b><small>Private-page impressions</small></div><div class="kpi"><b>10.07</b><small>Private-page position</small></div><div class="kpi"><b>3</b><small>Organic sessions</small></div><div class="kpi"><b>0</b><small>GA4 key events</small></div></div><div class="callout"><b>Critical interpretation:</b> GSC impressions are FairLend visibility, not market search volume. Volume/CPC/KD remain unavailable—not zero—because no compliant bulk metrics provider was connected.</div></section>
<section id="s2"><div class="sec-head"><span>02</span><h2>Evidence, with scope intact</h2></div><div class="evidence-grid"><article class="evidence-card"><h3>Fresh first-party</h3><p>GSC and GA4 were observed under <b>c.beleznay@humanfeedback.com</b>. The private borrower page is the only direct borrower-page signal in the small sample. GA4 has no key events, so lead quality cannot yet be validated.</p></article><article class="evidence-card"><h3>Current ranking patterns</h3><p>Prime/B results separate lender tiers. Bridge results separate firm-sale bank products from private no-firm-sale options. Renovation results expect budgets, appraisals, and advances. Rescue content is legally sensitive.</p></article><article class="evidence-card"><h3>Question discovery</h3><p>Answer Socrates/PAA-style patterns expanded who/what/how/can/versus/urgent questions. They are discovery signals, not numeric demand metrics.</p></article><article class="evidence-card"><h3>Unknown ≠ zero</h3><p>Monthly searches, CPC, and difficulty are blank until Keyword Planner or a paid provider is connected. Every dataset row preserves this status.</p></article></div></section>
<section id="s3"><div class="sec-head"><span>03</span><h2>Five-layer borrower funnel</h2></div><div class="funnel">${layers.map((l,i)=>`<article class="layer"><div class="num">${i+1}</div><h3>${htmlEscape(l[1].replaceAll('-',' '))}</h3><p>${htmlEscape(l[2])}</p><span class="count">${keywords.filter(k=>k.primaryFunnelLayer===l[0]).length} retained queries</span></article>`).join('')}</div></section>
<section id="s4"><div class="sec-head"><span>04</span><h2>Service opportunity matrix</h2></div><div class="table-wrap"><table><thead><tr><th>Priority</th><th>Service</th><th>First-party signal</th><th>Current SERP pattern</th><th>Action</th><th>Confidence</th></tr></thead><tbody>${opportunityRows}</tbody></table></div></section>
<section id="s5"><div class="sec-head"><span>05</span><h2>Canonical content architecture</h2></div><p class="lead">These are page owners, not keyword buckets. Each card carries the borrower problem, outcome, CTA, internal links, and the boundary that keeps it from eating a neighbouring page.</p><div class="cluster-toolbar"><button class="active" data-cluster-filter="all">All</button><button data-cluster-filter="P0">P0</button><button data-cluster-filter="P1">P1</button><button data-cluster-filter="P2">P2</button><button data-cluster-filter="Hold">Hold</button></div><div class="clusters">${clusterCards}</div></section>
<section id="s6"><div class="sec-head"><span>06</span><h2>Cannibalization contract</h2></div><div class="rules">${boundaryRows}</div></section>
<section id="s7"><div class="sec-head"><span>07</span><h2>Keyword universe</h2></div><p class="lead">Search, filter, and inspect every retained query. The “ranking pages” are the current segment/cluster-primary SERP owners used to validate page type; the dataset does not claim they hold the same rank for each long tail.</p><div class="explorer-controls"><input id="kwSearch" placeholder="Search query, owner, or rationale"><select id="kwSegment"><option value="">All services</option>${segments.map(s=>`<option value="${s.id}">${htmlEscape(s.name)}</option>`).join('')}</select><select id="kwLayer"><option value="">All layers</option>${layers.map(l=>`<option value="${l[0]}">${l[0]} · ${htmlEscape(l[1])}</option>`).join('')}</select><select id="kwPriority"><option value="">All priorities</option><option>P0</option><option>P1</option><option>P2</option><option>Hold</option></select></div><p class="count"><span id="kwCount">${keywords.length}</span> matching keywords</p><div class="table-wrap"><table id="keywordTable"><thead><tr><th>Query</th><th>Service</th><th>Layer</th><th>Intent</th><th>Owner</th><th>Priority</th><th>Market numbers</th><th>FairLend GSC</th><th>Current ranking pages</th></tr></thead><tbody>${keywords.map(k=>`<tr data-segment="${k.segmentId}" data-layer="${k.primaryFunnelLayer}" data-priority="${k.priority}"><td><b>${htmlEscape(k.query)}</b><small>${htmlEscape(k.confidence)} confidence</small></td><td>${htmlEscape(k.segmentName)}</td><td>${k.primaryFunnelLayer}</td><td>${htmlEscape(k.intent)}</td><td><code>${htmlEscape(k.targetPath)}</code></td><td><span class="badge ${k.priority.toLowerCase()}">${k.priority}</span></td><td>${htmlEscape(k.marketMetricStatus)}</td><td>${htmlEscape(k.fairlendGscStatus)}${k.gscImpressions!==''?`<small>${k.gscImpressions} impressions · position ${k.gscPosition}</small>`:''}</td><td>${k.currentRankingUrls.split(' | ').map((u,i)=>`<a href="${htmlEscape(u)}" target="_blank">#${i+1}</a>`).join(' · ')}<small>${htmlEscape(k.rankingScope)}</small></td></tr>`).join('')}</tbody></table></div></section>
<section id="s8"><div class="sec-head"><span>08</span><h2>Question and answer system</h2></div><div class="explorer-controls"><input id="qSearch" placeholder="Search borrower questions"><select id="qSegment"><option value="">All services</option>${segments.map(s=>`<option value="${s.id}">${htmlEscape(s.name)}</option>`).join('')}</select><select id="qLayer"><option value="">All layers</option>${layers.map(l=>`<option value="${l[0]}">${l[0]} · ${htmlEscape(l[1])}</option>`).join('')}</select><span></span></div><p class="count"><span id="qCount">${questions.length}</span> matching questions</p><div class="table-wrap"><table id="questionTable"><thead><tr><th>Question</th><th>Service</th><th>Layer</th><th>Owner</th><th>Answer format</th></tr></thead><tbody>${questions.map(q=>`<tr data-segment="${q.segmentId}" data-layer="${q.primaryFunnelLayer}"><td><b>${htmlEscape(q.question)}</b></td><td>${htmlEscape(q.segmentName)}</td><td>${q.primaryFunnelLayer}</td><td><code>${htmlEscape(q.targetPath)}</code></td><td>${htmlEscape(q.answerFormat)}</td></tr>`).join('')}</tbody></table></div></section>
<section id="s9"><div class="sec-head"><span>09</span><h2>90-day publishing system</h2></div><div class="roadmap"><article class="phase"><span class="eyebrow" style="color:#17613f">Days 1–14</span><h3>Repair</h3><ul><li>Configure GA4 key events</li><li>Strengthen private owner</li><li>Refocus institutional/A owner</li><li>Set query→page export</li></ul></article><article class="phase"><span class="eyebrow" style="color:#17613f">Days 15–30</span><h3>Decide</h3><ul><li>A/B/private comparison</li><li>Mortgage-decline triage</li><li>Reusable comparison and checklist blocks</li><li>Legal review gate</li></ul></article><article class="phase"><span class="eyebrow" style="color:#17613f">Days 31–60</span><h3>Expand</h3><ul><li>B guide and service</li><li>HELOC guide and service</li><li>Renovation system</li><li>Equity comparison</li></ul></article><article class="phase"><span class="eyebrow" style="color:#17613f">Days 61–90</span><h3>Validate</h3><ul><li>Bridge guide and service</li><li>A requirements guide</li><li>Conditional residential build</li><li>28/90-day GSC + GA4 review</li></ul></article></div></section>
<section id="s10"><div class="sec-head"><span>10</span><h2>Measurement and decision rules</h2></div><div class="table-wrap"><table><thead><tr><th>Signal</th><th>System</th><th>Cadence</th><th>Decision</th></tr></thead><tbody><tr><td>Non-brand impressions by cluster</td><td>GSC query→page</td><td>Weekly</td><td>Confirms discovery and exposes wrong-page ranking</td></tr><tr><td>CTR at positions 4–15</td><td>GSC</td><td>Biweekly</td><td>Rewrite title/meta after sufficient impressions</td></tr><tr><td>Assessment starts/completions</td><td>GA4 key events</td><td>Weekly</td><td>Primary conversion validation after setup</td></tr><tr><td>Qualified-lead rate</td><td>CRM + GA4</td><td>Monthly</td><td>Changes commercial priority</td></tr><tr><td>Two pages for one query family</td><td>GSC query→page</td><td>Monthly</td><td>Merge, redirect, or narrow boundary</td></tr><tr><td>Volume/CPC/KD refresh</td><td>Keyword Planner / paid provider</td><td>On connection</td><td>Re-score roadmap without casually changing owners</td></tr></tbody></table></div><div class="callout"><b>Revalidation trigger:</b> run at 28 days and day 90, or when a cluster reaches 100 non-brand impressions—whichever comes first.</div></section>
<footer>FairLend borrower SEO operating brief · Generated ${observedAt} · Ontario canonical, Toronto/GTA only where materially distinct · Investor-only intent excluded.</footer></div></div><script>
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];$$('[data-cluster-filter]').forEach(b=>b.onclick=()=>{$$('[data-cluster-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.cluster').forEach(c=>c.hidden=b.dataset.clusterFilter!=='all'&&c.dataset.priority!==b.dataset.clusterFilter)});
function filterTable(type){const isKw=type==='kw',search=$('#'+type+'Search').value.toLowerCase(),segment=$('#'+type+'Segment').value,layer=$('#'+type+'Layer').value,priority=isKw?$('#kwPriority').value:'';let n=0;$$('#'+(isKw?'keywordTable':'questionTable')+' tbody tr').forEach(r=>{const ok=(!search||r.innerText.toLowerCase().includes(search))&&(!segment||r.dataset.segment===segment)&&(!layer||r.dataset.layer===layer)&&(!priority||r.dataset.priority===priority);r.hidden=!ok;if(ok)n++});$('#'+type+'Count').textContent=n}['kwSearch','kwSegment','kwLayer','kwPriority'].forEach(id=>$('#'+id).addEventListener(id==='kwSearch'?'input':'change',()=>filterTable('kw')));['qSearch','qSegment','qLayer'].forEach(id=>$('#'+id).addEventListener(id==='qSearch'?'input':'change',()=>filterTable('q')));
const links=$$('.toc a'),sections=$$('section[id]');const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){links.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}}),{rootMargin:'-20% 0px -70% 0px'});sections.forEach(s=>io.observe(s));
</script></body></html>`;
}

const qa=[];
function check(gate,passed,detail){qa.push({gate,status:passed?'PASS':'FAIL',detail});if(!passed) process.exitCode=1;}
check('retained-keyword-count',keywords.length===160,`Expected 160; found ${keywords.length}`);
check('segment-coverage',new Set(keywords.map(k=>k.segmentId)).size===8,'All 8 segments present');
check('layer-coverage',segments.every(s=>new Set(keywords.filter(k=>k.segmentId===s.id).map(k=>k.primaryFunnelLayer)).size===5),'Every segment covers all 5 layers');
check('unique-normalized-query',new Set(keywords.map(k=>k.normalizedQuery)).size===keywords.length,'Every retained query is globally unique');
check('exactly-one-cluster',keywords.every(k=>k.clusterId&&clusters.filter(c=>c.id===k.clusterId).length===1),'Every keyword maps to exactly one defined cluster');
check('one-primary-layer',keywords.every(k=>/^L[1-5]$/.test(k.primaryFunnelLayer)),'Every keyword has exactly one valid primary layer');
check('cluster-owner-unique',new Set(clusters.map(c=>c.path)).size===clusters.length,'Every page cluster has one unique canonical path');
check('cluster-required-fields',clusters.every(c=>['id','name','segments','primary','path','status','priority','type','layers','problem','outcome','sections','cta','links','boundary','evidenceRefs','evidenceConfidence','marketMetricStatus','rankingValidationScope'].every(f=>c[f])),'All page briefs contain execution, evidence, confidence, and validation fields');
check('market-metrics-not-fabricated',keywords.every(k=>k.marketMetricStatus==='unavailable-not-zero'&&k.monthlySearches===''&&k.cpc===''&&k.difficulty===''),'Unavailable metrics remain blank and distinct from zero');
check('investor-intent-excluded',keywords.every(k=>!/(invest in private mortgages|private mortgage investment|mortgage fund|mortgage investor)/i.test(k.query)),'Investor-only intent excluded');
check('question-coverage',questions.length===120&&segments.every(s=>layers.every(l=>questions.filter(q=>q.segmentId===s.id&&q.primaryFunnelLayer===l[0]).length===3)),'120 questions; 3 per segment-layer');
check('ranking-evidence-present',keywords.every(k=>k.currentRankingUrls.split(' | ').length===3),'Every keyword carries three current segment/cluster ranking references with scoped claim');
check('keyword-validation-row-coverage',keywordValidation.length===keywords.length&&new Set(keywordValidation.map(r=>r.keywordId)).size===keywords.length,'Demand and ranking validation contains exactly one row per retained keyword');
check('gsc-unobserved-distinct-from-zero',keywordValidation.filter(r=>r.gscImpressions==='').every(r=>r.fairlendGscStatus.includes('not observed')),'Missing GSC query observations are explicitly not observed, never zero');

fs.mkdirSync(outputDir,{recursive:true});fs.mkdirSync(path.dirname(htmlPath),{recursive:true});
const artifacts={
  'keyword-universe.csv':csv(keywords),
  'keyword-demand-and-ranking-validation.csv':csv(keywordValidation),
  'page-cluster-map.csv':csv(clusters),
  'question-bank.csv':csv(questions),
  'evidence-ledger.csv':csv(evidence),
  'service-opportunity-matrix.csv':csv(opportunities),
  'coverage-qa.csv':csv(qa),
  'mortgage-borrower-keyword-research-and-strategy.md':fullReport(),
  '90-day-roadmap.md':roadmap(),
  'research-summary.json':JSON.stringify({generatedAt:observedAt,market:'Ontario; Toronto/GTA only where materially distinct',account:'c.beleznay@humanfeedback.com',counts:{keywords:keywords.length,keywordValidationRows:keywordValidation.length,clusters:clusters.length,questions:questions.length,evidence:evidence.length,segments:segments.length,layers:layers.length},firstParty:{gsc:{clicks:2,impressions:67,ctr:0.03,averagePosition:31.2,exactKeywordRowsObserved:keywordValidation.filter(r=>r.gscImpressions!=='').length,keywordRowsNotObserved:keywordValidation.filter(r=>r.gscImpressions==='').length,privatePage:{clicks:0,impressions:14,averagePosition:10.07}},ga4:{dateRange:'2026-06-22/2026-07-19',sessions:18,engagedSessions:14,organicSessions:3,organicEngagedSessions:2,organicEngagementRate:0.6667,organicAverageEngagementSeconds:77,organicEvents:23,keyEvents:0}},metricStatus:'market volume/CPC/difficulty unavailable-not-zero',rankingStatus:'three representative cluster-primary ranking URLs per keyword; exact long-tail positions unavailable',qa},null,2)+'\n',
  'run-manifest.json':JSON.stringify({generatedAt:observedAt,objective:'Ontario borrower keyword research, five-layer clustering, Google validation, content proposal, and interactive visual brief',inputs:['FairLend site/repo inventory','Authenticated GSC UI','Authenticated GA4 UI','Answer Socrates question discovery','Current web SERP evidence','Prior FairLend SEO research'],outputs:['mortgage-borrower-keyword-research-and-strategy.md','keyword-universe.csv','keyword-demand-and-ranking-validation.csv','page-cluster-map.csv','question-bank.csv','evidence-ledger.csv','service-opportunity-matrix.csv','90-day-roadmap.md','coverage-qa.csv','research-summary.json',htmlPath],limitations:['No callable market-volume provider','Small first-party sample','No bulk exact Google rank tracker','Zero GA4 key events'],qaStatus:qa.every(x=>x.status==='PASS')?'PASS':'FAIL'},null,2)+'\n',
};
artifacts['README.md']=`# FairLend mortgage-borrower SEO strategy — ${observedAt}\n\nComplete evidence-backed strategy for eight borrower services across five funnel layers.\n\n## Deliverables\n\n${Object.keys(artifacts).map(n=>`- \`${n}\``).join('\n')}\n- \`${htmlPath}\` — self-contained interactive visual brief\n\n## Data contract\n\nMarket volume, CPC, and difficulty are blank because no live provider was callable. They are marked \`unavailable-not-zero\`. GSC metrics are FairLend first-party visibility, not market demand. Ranking URLs validate segment/cluster-primary SERP patterns; exact rank for every long tail is not claimed.\n`;
for(const [name,content] of Object.entries(artifacts)) fs.writeFileSync(path.join(outputDir,name),content);
